local KTool = CS.Engine.Lib.KTool
local cs_coroutine = require 'XLua.cs_coroutine'
local UIModule = CS.Engine.UI.UIModule
local Yielders = CS.Engine.Lib.Yielders
--- from: Assets/BundleResources/Prefabs/Activity/ActivityCrisisContractDialog120015.prefab > name: ActivityCrisisContractDialog120015
---@class ActivityCrisisContractDialog
---@field Env                           	ActivityCrisisContractDialog            
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field BtnEntrance                   	UnityEngine.RectTransform               	@ 0    
---@field StateText                     	UnityEngine.UI.Text                     	@ 1    
---@field ImgTitleName                  	Engine.UI.WebRawImage                   	@ 2    
---@field TxtTime                       	TMPro.TextMeshProUGUI                   	@ 3    
---@field Open                          	UnityEngine.RectTransform               	@ 4    
---@field Close                         	UnityEngine.RectTransform               	@ 5    
---@field TextTime2                     	UnityEngine.RectTransform               	@ 6    
local ActivityCrisisContractDialog = Class('ActivityCrisisContractDialog')
local ActivityCrisisUtils = import('Game.Activity.CrisisContract.ActivityCrisisUtils')

function ActivityCrisisContractDialog:__init()
    self.activityData = nil
end

function ActivityCrisisContractDialog:__delete()
    self.activityData = nil
end

function ActivityCrisisContractDialog:Awake()
    self:AddUIClick()
end

function ActivityCrisisContractDialog:AddUIClick()
    SetButtonAction(self.BtnEntrance.gameObject,Bind(self,self.OnBtnEnterClick))
end

function ActivityCrisisContractDialog:OnBtnEnterClick()
    local isUnlock = self:IsUnLock()
    if not isUnlock then
        GameUtils.Toast(self:GetUnLockDesc())
        return
    end
    cs_coroutine.start(function()
        UIModule.OpenDialog({ id = Constants.UITypeIds.ActivityCrisisContractAnimation})
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
        cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.ActivityCrisisContractMain}, { { id = Constants.UITypeIds.UIActivityMainDialog } }))
    end)
end

function ActivityCrisisContractDialog:IsUnLock()
    local isUnlock = GameUtils.IsUnlockedSingle(self.activityData.unlock[1].targetType, self.activityData.unlock[1].targetNum, self.activityData.unlock[1].targetId)
    return isUnlock
end

function ActivityCrisisContractDialog:GetUnLockDesc()
    local unLockDesc = GameUtils.GetUnlockDescr(self.activityData.unlock[1].targetType, self.activityData.unlock[1].targetNum, self.activityData.unlock[1].targetId)
    return unLockDesc
end

function ActivityCrisisContractDialog:Refresh(data)
    self.activityData = data
    ---@type ActivityCrisisUtils
    ActivityCrisisUtils.GetActivityCrisisMgr():SaveActivityData(self.activityData)
    self:SetTitle()
    self:SetTimeShow()
    self:RefreshLockState()
end

function ActivityCrisisContractDialog:RefreshLockState()
    local isUnlock = self:IsUnLock()
    KTool.SetActive(self.Open.gameObject,isUnlock)
    KTool.SetActive(self.Close.gameObject,not isUnlock)
end

function ActivityCrisisContractDialog:SetTimeShow()
    --region 时间
    local startTime =  self.activityData.startTime
    local closeTime =  self.activityData.closeTime
    local ActivityUtils         = import("Game.Activity.ActivityUtils")
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(startTime, closeTime))
    local endTimeLeave =  ActivityUtils.ConventLeftTimeText(self.activityData.endTime)
    CfUtils.FillText(self.TextTime2, endTimeLeave)
end

function ActivityCrisisContractDialog:SetTitle()
    CfUtils.FillText(self.StateText,self.activityData.detail)

    local titleImgUrl = checkString(self.activityData.titleImage)
    if string.len(titleImgUrl) > 0 then
        CfUtils.FillWebRawImage(self.ImgTitleName, titleImgUrl)
    end
end

function ActivityCrisisContractDialog:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ActivityCrisisContractDialog